def structured_menu_context(nodes):
    """Recognize a partially shown product grid using independent, scoped shop controls."""
    from control.accessible_order import observe_named_region, region_kind
    from control.category_memory import is_catalog_label
    from control.menu_observation import _product_name, menu_group, selected_state

    regions, filters, products = [], [], set()
    for node in nodes:
        if not node.is_visible():
            continue
        info = node.element_info
        role, name = info.control_type, (info.name or '').strip()
        aria = getattr(info.element, 'CurrentAriaRole', '')
        if aria in ('dialog', 'alertdialog') or role in ('Edit', 'ComboBox'):
            return False
        if region_kind(name) == 'basket' and aria in ('complementary','region'):
            regions.append(node)
        elif menu_group(name,role) == 'categories':
            filters.append(node)
        elif role == 'Button' and (item := _product_name(role,name)) and is_catalog_label(item) and node.is_enabled():
            products.add(item)
    if len(regions) != 1 or len(filters) != 1 or len(products) < 2:
        return False
    choices = [selected_state(n, n.element_info.control_type) for n in filters[0].descendants()
               if n.element_info.control_type in ('Button', 'TabItem', 'RadioButton') and n.is_visible()]
    if len(choices) < 2 or None in choices or choices.count(True) != 1:
        return False
    state = {}
    observe_named_region(state, regions)
    return state.get('basket_sheet') == {'rows': {}, 'total': 0}

